using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OptimizeEffect", menuName = "Data/Battle/Effects/Hevelius/Optimize Effect")]
public class OptimizeEffect : Effect
{
	[Header("Corrupt Action")]
	[SerializeField]
	private BattleAction battleActionToChange;

	[SerializeField]
	private int amountToChange;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, battleActionToChange.GetActionName(), amountToChange, GetNumberToReplaceWithX());
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), battleActionToChange.GetActionName(), amountToChange, amount);
	}

	public Dice TurnPurifiesIntoNewAction(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			DiceFace diceFace = dice.GetDiceFaces()[i];
			if (diceFace.BattleAction is PurifyAction)
			{
				diceFace.BattleAction = battleActionToChange;
				diceFace.ActionValue = amountToChange;
			}
			if (dice.GetDiceFaces()[i].EnableSecondAction && diceFace.SecondBattleAction is PurifyAction)
			{
				diceFace.SecondBattleAction = battleActionToChange;
				diceFace.SecondActionValue = amountToChange;
			}
			dice.GetDiceFaces()[i] = diceFace;
		}
		return dice;
	}
}
